keyboard_visualviewport_offset_reset.workaround_js:
'use client';
import { useEffect } from 'react';

// Attach in root layout client component
export function ViewportKeyboardFix() {
  useEffect(() => {
    if (!window.visualViewport) return;
    const handleResize = () => {
      // When keyboard dismisses, offsetTop should be 0
      if (window.visualViewport.offsetTop > 0 &&
          window.visualViewport.height === window.innerHeight) {
        // Keyboard dismissed but offset not reset
        window.scrollTo(0, window.scrollY); // force repaint
      }
    };
    window.visualViewport.addEventListener('resize', handleResize);
    return () => window.visualViewport.removeEventListener('resize', handleResize);
  }, []);
  return null;
}

