view_transitions.progressive_enhancement_pattern:
// React 19.2 <ViewTransition> component handles feature detection internally.
// On unsupported browsers: instant navigation, no animation, no error.
// Do NOT polyfill with JS animation libraries — adds bundle weight and
// does not replicate the compositing-layer snapshot model.

import { ViewTransition } from 'react';

// Correct usage — wrap elements that should animate:
function ProductCard({ product }: { product: Product }) {
  return (
    <ViewTransition key={product.id}>
      <article className="product-card">
        <img
          src={product.image}
          alt={product.name}
          style={{ viewTransitionName: `product-image-${product.id}` }}
        />
        <h2>{product.name}</h2>
      </article>
    </ViewTransition>
  );
}

