activity_component.pattern:
// Prefer Activity for lightweight state-heavy components (forms, filters)
// Unmount (conditional rendering) for heavy media components

import { Activity } from 'react';

function TabPanel({ tabs, activeTab }: { tabs: Tab[]; activeTab: string }) {
  return (
    <>
      {tabs.map(tab => (
        <Activity
          key={tab.id}
          mode={activeTab === tab.id ? 'visible' : 'hidden'}
        >
          {tab.isMediaHeavy
            ? activeTab === tab.id ? <tab.Component /> : null // unmount
            : <tab.Component />  // Activity preserve state
          }
        </Activity>
      ))}
    </>
  );
}

