smooth_scroll_safari.workaround_js:
// Use a polyfill or custom smooth scroll implementation
// Option 1: smoothscroll-polyfill
// import smoothscroll from 'smoothscroll-polyfill';
// smoothscroll.polyfill();

// Option 2: Manual requestAnimationFrame scroll
function smoothScrollTo(target: number, duration = 300) {
  const start = window.scrollY;
  const distance = target - start;
  let startTime: number | null = null;
  function step(timestamp: number) {
    if (!startTime) startTime = timestamp;
    const elapsed = timestamp - startTime;
    const progress = Math.min(elapsed / duration, 1);
    window.scrollTo(0, start + distance * easeInOut(progress));
    if (elapsed < duration) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}
function easeInOut(t: number) { return t < 0.5 ? 2*t*t : -1+(4-2*t)*t; }

